(521, 1, '2026-05-30 07:37:58', '2026-05-30 07:37:58', '{\n    \"custom_css[astra]\": {\n        \"value\": \" /* \\ud83c\\udf38 Blog Background */\\nbody.blog {\\n    background: #fff0f5;\\n}\\n\\n/* \\ud83c\\udf38 Grid layout */\\n.blog .site-content .ast-container,\\n.blog .site-content {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\\n    gap: 25px;\\n}\\n\\n/* \\ud83c\\udf38 Post Card */\\n.blog .post,\\n.blog article {\\n    background: #ffffff;\\n    border-radius: 18px;\\n    overflow: hidden;\\n    box-shadow: 0 8px 25px rgba(0,0,0,0.08);\\n    transition: all 0.3s ease;\\n}\\n\\n/* \\ud83c\\udf38 Hover effect */\\n.blog .post:hover,\\n.blog article:hover {\\n    transform: translateY(-8px);\\n    box-shadow: 0 15px 35px rgba(255, 105, 180, 0.25);\\n}\\n\\n/* \\ud83c\\udf38 Featured Image */\\n.blog .post img,\\n.blog article img {\\n    width: 100%;\\n    height: 220px;\\n    object-fit: cover;\\n    transition: 0.4s ease;\\n}\\n\\n.blog .post:hover img,\\n.blog article:hover img {\\n    transform: scale(1.05);\\n}\\n\\n/* \\ud83c\\udf38 Content padding */\\n.blog .entry-content,\\n.blog .entry-header {\\n    padding: 15px 18px;\\n}\\n\\n/* \\ud83c\\udf38 Title */\\n.blog .entry-title a {\\n    font-size: 18px;\\n    font-weight: 600;\\n    color: #333;\\n    text-decoration: none;\\n}\\n\\n.blog .entry-title a:hover {\\n    color: #ff4da6;\\n}\\n\\n/* \\ud83c\\udf38 Read More button */\\n.blog .more-link {\\n    display: inline-block;\\n    margin-top: 10px;\\n    padding: 8px 14px;\\n    background: #ff4da6;\\n    color: #fff;\\n    border-radius: 25px;\\n    font-size: 13px;\\n    text-decoration: none;\\n    transition: 0.3s;\\n}\\n\\n.blog .more-link:hover {\\n    background: #ff2f92;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-30 07:37:58\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '2617ac6a-fe7b-499f-bd8a-8d067ae87193', '', '', '2026-05-30 07:37:58', '2026-05-30 07:37:58', '', 0, 'http://localhost/habibi/?p=521', 0, 'customize_changeset', '', 0),
(522, 1, '2026-05-30 07:37:58', '2026-05-30 07:37:58', '\n/* 💗 بک‌گراند */\nbody.blog {\n    background: #fff0f5;\n}\n\n/* 🌸 فقط فاصله دادن، نه تغییر layout */\n.blog .ast-container {\n    padding: 30px;\n}\n\n/* 🌸 فاصله بین پست‌ها (مهم‌ترین بخش) */\n.blog article {\n    margin-bottom: 25px;\n}\n\n/* 🌸 کارت شیک */\n.blog article {\n    background: #fff;\n    border-radius: 16px;\n    overflow: hidden;\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\n    transition: all 0.3s ease;\n}\n\n/* 🌸 hover نرم */\n.blog article:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\n}\n\n/* 🌸 تصویر کوتاه */\n.blog article img {\n    width: 100%;\n    height: 170px;\n    object-fit: cover;\n}\n\n/* 🌸 متن */\n.blog .entry-content,\n.blog .entry-header {\n    padding: 12px 14px;\n}\n\n/* 🌸 عنوان */\n.blog .entry-title a {\n    font-size: 16px;\n    color: #333;\n}\n\n/* 🌸 دکمه */\n.blog .more-link {\n    display: inline-block;\n    margin-top: 10px;\n    padding: 8px 16px;\n    background: linear-gradient(135deg, #ff4da6, #ff8cc6);\n    color: #fff;\n    border-radius: 30px;\n}', 'astra', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2026-05-30 07:45:11', '2026-05-30 07:45:11', '', 0, 'http://localhost/habibi/index.php/2026/05/30/astra/', 0, 'custom_css', '', 0),
(523, 1, '2026-05-30 07:37:58', '2026-05-30 07:37:58', ' /* 🌸 Blog Background */\nbody.blog {\n    background: #fff0f5;\n}\n\n/* 🌸 Grid layout */\n.blog .site-content .ast-container,\n.blog .site-content {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 25px;\n}\n\n/* 🌸 Post Card */\n.blog .post,\n.blog article {\n    background: #ffffff;\n    border-radius: 18px;\n    overflow: hidden;\n    box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n    transition: all 0.3s ease;\n}\n\n/* 🌸 Hover effect */\n.blog .post:hover,\n.blog article:hover {\n    transform: translateY(-8px);\n    box-shadow: 0 15px 35px rgba(255, 105, 180, 0.25);\n}\n\n/* 🌸 Featured Image */\n.blog .post img,\n.blog article img {\n    width: 100%;\n    height: 220px;\n    object-fit: cover;\n    transition: 0.4s ease;\n}\n\n.blog .post:hover img,\n.blog article:hover img {\n    transform: scale(1.05);\n}\n\n/* 🌸 Content padding */\n.blog .entry-content,\n.blog .entry-header {\n    padding: 15px 18px;\n}\n\n/* 🌸 Title */\n.blog .entry-title a {\n    font-size: 18px;\n    font-weight: 600;\n    color: #333;\n    text-decoration: none;\n}\n\n.blog .entry-title a:hover {\n    color: #ff4da6;\n}\n\n/* 🌸 Read More button */\n.blog .more-link {\n    display: inline-block;\n    margin-top: 10px;\n    padding: 8px 14px;\n    background: #ff4da6;\n    color: #fff;\n    border-radius: 25px;\n    font-size: 13px;\n    text-decoration: none;\n    transition: 0.3s;\n}\n\n.blog .more-link:hover {\n    background: #ff2f92;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '522-revision-v1', '', '', '2026-05-30 07:37:58', '2026-05-30 07:37:58', '', 522, 'http://localhost/habibi/?p=523', 0, 'revision', '', 0),
(524, 1, '2026-05-30 07:40:47', '2026-05-30 07:40:47', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\ud83c\\udf38 Background */\\nbody.blog {\\n    background: #fff0f5;\\n}\\n\\n/* \\ud83c\\udf38 Blog Grid (\\u0627\\u0635\\u0644\\u0627\\u062d \\u0634\\u062f\\u0647) */\\n.blog .site-content .ast-container {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\\n    gap: 30px;\\n    padding: 30px;\\n}\\n\\n/* \\ud83c\\udf38 Post Card */\\n.blog article {\\n    background: #fff;\\n    border-radius: 16px;\\n    overflow: hidden;\\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\\n    transition: transform 0.4s ease, box-shadow 0.4s ease;\\n}\\n\\n/* \\ud83c\\udf38 Hover (\\u0646\\u0631\\u0645 \\u0648 \\u0628\\u062f\\u0648\\u0646 \\u062c\\u0647\\u0634 \\u062a\\u0646\\u062f) */\\n.blog article:hover {\\n    transform: translateY(-6px);\\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\\n}\\n\\n/* \\ud83c\\udf38 Image (\\u06a9\\u0648\\u0686\\u06cc\\u06a9\\u200c\\u062a\\u0631 \\u0648 \\u0634\\u06cc\\u06a9\\u200c\\u062a\\u0631) */\\n.blog article img {\\n    width: 100%;\\n    height: 180px;\\n    object-fit: cover;\\n    transition: transform 0.5s ease;\\n}\\n\\n/* \\ud83c\\udf38 Image hover (\\u0622\\u0631\\u0648\\u0645) */\\n.blog article:hover img {\\n    transform: scale(1.03);\\n}\\n\\n/* \\ud83c\\udf38 Content */\\n.blog .entry-content,\\n.blog .entry-header {\\n    padding: 12px 14px;\\n}\\n\\n/* \\ud83c\\udf38 Title */\\n.blog .entry-title a {\\n    font-size: 16px;\\n    font-weight: 600;\\n    color: #333;\\n    text-decoration: none;\\n}\\n\\n.blog .entry-title a:hover {\\n    color: #ff4da6;\\n}\\n\\n/* \\ud83c\\udf38 Button */\\n.blog .more-link {\\n    display: inline-block;\\n    margin-top: 10px;\\n    padding: 6px 12px;\\n    background: #ff4da6;\\n    color: #fff;\\n    border-radius: 20px;\\n    font-size: 12px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-30 07:40:26\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'ec65cfb4-3606-42f7-8c4b-459bc7e359ae', '', '', '2026-05-30 07:40:47', '2026-05-30 07:40:47', '', 0, 'http://localhost/habibi/?p=524', 0, 'customize_changeset', '', 0),
(525, 1, '2026-05-30 07:40:47', '2026-05-30 07:40:47', '/* 🌸 Background */\nbody.blog {\n    background: #fff0f5;\n}\n\n/* 🌸 Blog Grid (اصلاح شده) */\n.blog .site-content .ast-container {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n    gap: 30px;\n    padding: 30px;\n}\n\n/* 🌸 Post Card */\n.blog article {\n    background: #fff;\n    border-radius: 16px;\n    overflow: hidden;\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\n    transition: transform 0.4s ease, box-shadow 0.4s ease;\n}\n\n/* 🌸 Hover (نرم و بدون جهش تند) */\n.blog article:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\n}\n\n/* 🌸 Image (کوچیک‌تر و شیک‌تر) */\n.blog article img {\n    width: 100%;\n    height: 180px;\n    object-fit: cover;\n    transition: transform 0.5s ease;\n}\n\n/* 🌸 Image hover (آروم) */\n.blog article:hover img {\n    transform: scale(1.03);\n}\n\n/* 🌸 Content */\n.blog .entry-content,\n.blog .entry-header {\n    padding: 12px 14px;\n}\n\n/* 🌸 Title */\n.blog .entry-title a {\n    font-size: 16px;\n    font-weight: 600;\n    color: #333;\n    text-decoration: none;\n}\n\n.blog .entry-title a:hover {\n    color: #ff4da6;\n}\n\n/* 🌸 Button */\n.blog .more-link {\n    display: inline-block;\n    margin-top: 10px;\n    padding: 6px 12px;\n    background: #ff4da6;\n    color: #fff;\n    border-radius: 20px;\n    font-size: 12px;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '522-revision-v1', '', '', '2026-05-30 07:40:47', '2026-05-30 07:40:47', '', 522, 'http://localhost/habibi/?p=525', 0, 'revision', '', 0),
(526, 1, '2026-05-30 07:43:32', '2026-05-30 07:43:32', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\ud83d\\udc97 Background */\\nbody.blog {\\n    background: #fff0f5;\\n}\\n\\n/* \\ud83c\\udf38 \\u0645\\u0647\\u0645: \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u0686\\u0633\\u0628\\u06cc\\u062f\\u0646 \\u0622\\u06cc\\u062a\\u0645\\u200c\\u0647\\u0627 */\\n.blog .ast-container {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 55px;\\n    justify-content: center;\\n    padding: 30px;\\n}\\n\\n/* \\ud83c\\udf38 \\u06a9\\u0627\\u0631\\u062a \\u067e\\u0633\\u062a */\\n.blog article {\\n    width: 280px;\\n    background: #fff;\\n    border-radius: 16px;\\n    overflow: hidden;\\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\\n    transition: all 0.3s ease;\\n}\\n\\n/* \\ud83c\\udf38 hover \\u0646\\u0631\\u0645 */\\n.blog article:hover {\\n    transform: translateY(-6px);\\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\\n}\\n\\n/* \\ud83c\\udf38 \\u062a\\u0635\\u0648\\u06cc\\u0631 (\\u062d\\u0644 \\u0645\\u0634\\u06a9\\u0644 \\u0642\\u062f \\u0632\\u06cc\\u0627\\u062f) */\\n.blog article img {\\n    width: 100%;\\n    height: 160px;   /* \\ud83d\\udc48 \\u06a9\\u0648\\u062a\\u0627\\u0647\\u200c\\u062a\\u0631 \\u0634\\u062f */\\n    object-fit: cover;\\n}\\n\\n/* \\ud83c\\udf38 \\u0645\\u062d\\u062a\\u0648\\u0627 */\\n.blog .entry-content,\\n.blog .entry-header {\\n    padding: 10px 12px;\\n}\\n\\n/* \\ud83c\\udf38 \\u0639\\u0646\\u0648\\u0627\\u0646 */\\n.blog .entry-title a {\\n    font-size: 15px;\\n    font-weight: 600;\\n    color: #333;\\n}\\n\\n/* \\ud83c\\udf38 \\u0641\\u0627\\u0635\\u0644\\u0647 \\u0645\\u062a\\u0646 (\\u0642\\u062f \\u06a9\\u0627\\u0631\\u062a \\u06a9\\u0645\\u062a\\u0631 \\u0645\\u06cc\\u0634\\u0647) */\\n.blog .entry-content p {\\n    font-size: 13px;\\n    line-height: 1.4;\\n    max-height: 60px;\\n    overflow: hidden;\\n}\\n\\n/* \\ud83c\\udf38 \\u062f\\u06a9\\u0645\\u0647 */\\n.blog .more-link {\\n    display: inline-block;\\n    margin-top: 8px;\\n    padding: 6px 12px;\\n    background: #ff4da6;\\n    color: #fff;\\n    border-radius: 20px;\\n    font-size: 12px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-30 07:43:32\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'cde94a28-0c87-4b7f-b3b9-5413414073cc', '', '', '2026-05-30 07:43:32', '2026-05-30 07:43:32', '', 0, 'http://localhost/habibi/?p=526', 0, 'customize_changeset', '', 0),
(527, 1, '2026-05-30 07:43:32', '2026-05-30 07:43:32', '/* 💗 Background */\nbody.blog {\n    background: #fff0f5;\n}\n\n/* 🌸 مهم: جلوگیری از چسبیدن آیتم‌ها */\n.blog .ast-container {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 55px;\n    justify-content: center;\n    padding: 30px;\n}\n\n/* 🌸 کارت پست */\n.blog article {\n    width: 280px;\n    background: #fff;\n    border-radius: 16px;\n    overflow: hidden;\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\n    transition: all 0.3s ease;\n}\n\n/* 🌸 hover نرم */\n.blog article:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\n}\n\n/* 🌸 تصویر (حل مشکل قد زیاد) */\n.blog article img {\n    width: 100%;\n    height: 160px;   /* 👈 کوتاه‌تر شد */\n    object-fit: cover;\n}\n\n/* 🌸 محتوا */\n.blog .entry-content,\n.blog .entry-header {\n    padding: 10px 12px;\n}\n\n/* 🌸 عنوان */\n.blog .entry-title a {\n    font-size: 15px;\n    font-weight: 600;\n    color: #333;\n}\n\n/* 🌸 فاصله متن (قد کارت کمتر میشه) */\n.blog .entry-content p {\n    font-size: 13px;\n    line-height: 1.4;\n    max-height: 60px;\n    overflow: hidden;\n}\n\n/* 🌸 دکمه */\n.blog .more-link {\n    display: inline-block;\n    margin-top: 8px;\n    padding: 6px 12px;\n    background: #ff4da6;\n    color: #fff;\n    border-radius: 20px;\n    font-size: 12px;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '522-revision-v1', '', '', '2026-05-30 07:43:32', '2026-05-30 07:43:32', '', 522, 'http://localhost/habibi/?p=527', 0, 'revision', '', 0),
(528, 1, '2026-05-30 07:45:11', '2026-05-30 07:45:11', '{\n    \"custom_css[astra]\": {\n        \"value\": \"\\n/* \\ud83d\\udc97 \\u0628\\u06a9\\u200c\\u06af\\u0631\\u0627\\u0646\\u062f */\\nbody.blog {\\n    background: #fff0f5;\\n}\\n\\n/* \\ud83c\\udf38 \\u0641\\u0642\\u0637 \\u0641\\u0627\\u0635\\u0644\\u0647 \\u062f\\u0627\\u062f\\u0646\\u060c \\u0646\\u0647 \\u062a\\u063a\\u06cc\\u06cc\\u0631 layout */\\n.blog .ast-container {\\n    padding: 30px;\\n}\\n\\n/* \\ud83c\\udf38 \\u0641\\u0627\\u0635\\u0644\\u0647 \\u0628\\u06cc\\u0646 \\u067e\\u0633\\u062a\\u200c\\u0647\\u0627 (\\u0645\\u0647\\u0645\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0628\\u062e\\u0634) */\\n.blog article {\\n    margin-bottom: 25px;\\n}\\n\\n/* \\ud83c\\udf38 \\u06a9\\u0627\\u0631\\u062a \\u0634\\u06cc\\u06a9 */\\n.blog article {\\n    background: #fff;\\n    border-radius: 16px;\\n    overflow: hidden;\\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\\n    transition: all 0.3s ease;\\n}\\n\\n/* \\ud83c\\udf38 hover \\u0646\\u0631\\u0645 */\\n.blog article:hover {\\n    transform: translateY(-6px);\\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\\n}\\n\\n/* \\ud83c\\udf38 \\u062a\\u0635\\u0648\\u06cc\\u0631 \\u06a9\\u0648\\u062a\\u0627\\u0647 */\\n.blog article img {\\n    width: 100%;\\n    height: 170px;\\n    object-fit: cover;\\n}\\n\\n/* \\ud83c\\udf38 \\u0645\\u062a\\u0646 */\\n.blog .entry-content,\\n.blog .entry-header {\\n    padding: 12px 14px;\\n}\\n\\n/* \\ud83c\\udf38 \\u0639\\u0646\\u0648\\u0627\\u0646 */\\n.blog .entry-title a {\\n    font-size: 16px;\\n    color: #333;\\n}\\n\\n/* \\ud83c\\udf38 \\u062f\\u06a9\\u0645\\u0647 */\\n.blog .more-link {\\n    display: inline-block;\\n    margin-top: 10px;\\n    padding: 8px 16px;\\n    background: linear-gradient(135deg, #ff4da6, #ff8cc6);\\n    color: #fff;\\n    border-radius: 30px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-30 07:45:11\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '2a0bb256-d629-4b8f-90ca-a7b3de2966da', '', '', '2026-05-30 07:45:11', '2026-05-30 07:45:11', '', 0, 'http://localhost/habibi/index.php/2026/05/30/2a0bb256-d629-4b8f-90ca-a7b3de2966da/', 0, 'customize_changeset', '', 0),
(529, 1, '2026-05-30 07:45:11', '2026-05-30 07:45:11', '\n/* 💗 بک‌گراند */\nbody.blog {\n    background: #fff0f5;\n}\n\n/* 🌸 فقط فاصله دادن، نه تغییر layout */\n.blog .ast-container {\n    padding: 30px;\n}\n\n/* 🌸 فاصله بین پست‌ها (مهم‌ترین بخش) */\n.blog article {\n    margin-bottom: 25px;\n}\n\n/* 🌸 کارت شیک */\n.blog article {\n    background: #fff;\n    border-radius: 16px;\n    overflow: hidden;\n    box-shadow: 0 6px 18px rgba(0,0,0,0.08);\n    transition: all 0.3s ease;\n}\n\n/* 🌸 hover نرم */\n.blog article:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 12px 28px rgba(255, 105, 180, 0.18);\n}\n\n/* 🌸 تصویر کوتاه */\n.blog article img {\n    width: 100%;\n    height: 170px;\n    object-fit: cover;\n}\n\n/* 🌸 متن */\n.blog .entry-content,\n.blog .entry-header {\n    padding: 12px 14px;\n}\n\n/* 🌸 عنوان */\n.blog .entry-title a {\n    font-size: 16px;\n    color: #333;\n}\n\n/* 🌸 دکمه */\n.blog .more-link {\n    display: inline-block;\n    margin-top: 10px;\n    padding: 8px 16px;\n    background: linear-gradient(135deg, #ff4da6, #ff8cc6);\n    color: #fff;\n    border-radius: 30px;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '522-revision-v1', '', '', '2026-05-30 07:45:11', '2026-05-30 07:45:11', '', 522, 'http://localhost/habibi/?p=529', 0, 'revision', '', 0);
